//! Reusable component CSS emitter. Only validated YAML tokens become CSS values.
use super::Theme;
use std::fmt::Write;
pub(crate) fn emit(t: &Theme) -> String {
    let mut s=format!(":root{{--bg:{};--surface:{};--raised:{};--border:{};--text:{};--muted:{};--accent:{};--warning:{};--error:{};--font:{}px;--radius:{}px;--gap:{}px;--sidebar:{}px;--details:{}px;}}\n",t.background,t.surface,t.raised,t.border,t.text,t.muted,t.accent,t.warning,t.error,t.font_px,t.radius_px,t.spacing_px,t.sidebar_px,t.details_px);
    // Mechanism-level control styles, reused by non-IDE component fixtures.
    s.push_str(r#"*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:var(--bg);color:var(--text);font:var(--font)/1.5 ui-sans-serif,system-ui,sans-serif}button,input,select{font:inherit}button,input,select{border:1px solid var(--border);border-radius:calc(var(--radius)/2);background:var(--raised);color:var(--text);min-height:38px}button{padding:7px 13px;cursor:pointer;font-weight:600}button:hover:enabled{border-color:var(--accent)}button:disabled{opacity:.45;cursor:default}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:3px}input,select{padding:7px 10px;max-width:100%}input{min-width:200px}h1,h2,p{margin:0}h1{font-size:21px;letter-spacing:-.5px}h2{font-size:12px;text-transform:uppercase;letter-spacing:1.5px;color:var(--muted);margin-bottom:var(--gap)}p{overflow-wrap:anywhere}p:not([role=status]){color:var(--muted)}[role=status]{color:var(--accent);font-weight:600;padding:5px 0}.fg-header{padding:23px 28px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;gap:var(--gap)}.fg-header>p{font-size:12px}.fg-brand{display:flex;align-items:center;gap:11px}.fg-mark{display:grid;place-items:center;width:30px;height:30px;border:1px solid var(--accent);color:var(--accent);font-weight:800;border-radius:7px}.fg-app{padding:20px 28px;display:grid;gap:var(--gap)}.fg-panel{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);padding:16px;min-width:0}.fg-panel .fg-panel{margin:12px 0;background:var(--bg)}.fg-row{display:flex;gap:var(--gap);align-items:flex-end;flex-wrap:wrap;margin:12px 0}.fg-field{display:grid;gap:5px;min-width:160px}.fg-field>span{font-size:11px;color:var(--muted);font-weight:600;letter-spacing:.3px}.fg-workspace{display:grid;grid-template-columns:minmax(180px,var(--sidebar)) minmax(250px,1fr) minmax(230px,var(--details));gap:var(--gap);min-height:430px}.fg-tree{max-height:63vh;overflow:auto;margin:12px -8px 0;padding:0 8px 8px;scrollbar-color:var(--border) var(--surface)}.fg-tree-row{display:flex;align-items:center;gap:2px;margin:3px 0;min-width:0}.fg-tree-row[data-selected=true]{background:var(--raised);border-radius:5px;box-shadow:inset 2px 0 var(--accent)}.fg-tree-row button{background:transparent;border:0;font-weight:400;text-align:left;min-height:31px;padding:4px 7px}.fg-row-select{display:flex;align-items:center;gap:8px;flex:1;min-width:0}.fg-row-label{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.fg-row-secondary{font-size:10px;color:var(--muted);margin-left:auto;white-space:nowrap}.fg-toggle{width:25px;flex:none;color:var(--muted);padding:4px!important}.fg-empty{padding:20px 0;font-size:12px}.fg-details{margin:10px 0 0;display:grid;gap:5px;overflow-wrap:anywhere}.fg-details dt{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.4px;margin-top:9px}.fg-details dd{margin:0;font-family:ui-monospace,monospace;font-size:12px;white-space:pre-wrap}.fg-app>p:last-child{font-size:11px}section>p{margin-bottom:8px}[hidden]{display:none!important}@media(max-width:1050px){.fg-workspace{grid-template-columns:minmax(180px,1fr) minmax(250px,2fr)}.fg-workspace>.fg-panel:last-child{grid-column:1/-1}.fg-header{align-items:flex-start}}@media(max-width:640px){.fg-header{padding:16px;display:block}.fg-header>p{margin-top:9px}.fg-app{padding:12px}.fg-workspace{display:flex;flex-direction:column}.fg-tree{max-height:42vh}.fg-field{width:100%}.fg-field select{width:100%}.fg-row button{flex:1}.fg-panel{padding:12px}.fg-row{gap:8px}}
"#);
    for n in 0..=64 {
        let _ = writeln!(s, ".fg-depth-{n}{{margin-inline-start:{}px}}", n * 12);
    }
    s
}
